def depth(value):
    if not isinstance(value, list):
        return 0
    if not value:
        return 1
    return 1 + max(depth(item) for item in value)

def summarize(lines):
    words = set()
    for line in lines:
        words.update(line.split())
    return len(lines), len(words)
